package license

import (
	"crypto/ed25519"
	"errors"
	"math/big"
)

// Ed25519 verification itself accepts some low-order public points for RFC
// 8032 compatibility. Such points are not safe trust anchors: the identity
// point, for example, admits a message-independent zero-scalar signature.
// Key import therefore requires the canonical encoding of a non-identity point
// in the prime-order subgroup generated by the Ed25519 base point.

var (
	edwardsP = func() *big.Int {
		p := new(big.Int).Lsh(big.NewInt(1), 255)
		return p.Sub(p, big.NewInt(19))
	}()
	edwardsD = func() *big.Int {
		numerator := new(big.Int).Neg(big.NewInt(121665))
		numerator.Mod(numerator, edwardsP)
		inverse := new(big.Int).ModInverse(big.NewInt(121666), edwardsP)
		return new(big.Int).Mod(new(big.Int).Mul(numerator, inverse), edwardsP)
	}()
	edwardsTwoD  = new(big.Int).Mod(new(big.Int).Lsh(new(big.Int).Set(edwardsD), 1), edwardsP)
	edwardsOrder = func() *big.Int {
		order := new(big.Int).Lsh(big.NewInt(1), 252)
		tail, ok := new(big.Int).SetString("27742317777372353535851937790883648493", 10)
		if !ok {
			panic("license: invalid Ed25519 order constant")
		}
		return order.Add(order, tail)
	}()
)

type extendedEdwardsPoint struct {
	x *big.Int
	y *big.Int
	z *big.Int
	t *big.Int
}

// ValidateEd25519PublicKey rejects malformed, non-canonical, identity,
// low-order, and mixed-order public points. Call it before trusting any raw
// Ed25519 public key outside the constructors in this package.
func ValidateEd25519PublicKey(encoded []byte) error {
	if len(encoded) != ed25519.PublicKeySize {
		return errors.New("invalid Ed25519 public key length")
	}
	point, err := decodeEd25519Point(encoded)
	if err != nil {
		return err
	}
	if point.isIdentity() {
		return errors.New("Ed25519 identity public key is not allowed")
	}
	if !edwardsScalarMult(point, edwardsOrder).isIdentity() {
		return errors.New("Ed25519 public key is not in the prime-order subgroup")
	}
	return nil
}

func decodeEd25519Point(encoded []byte) (extendedEdwardsPoint, error) {
	value := append([]byte(nil), encoded...)
	xSign := uint(value[31] >> 7)
	value[31] &= 0x7f
	y := littleEndianInteger(value)
	if y.Cmp(edwardsP) >= 0 {
		return extendedEdwardsPoint{}, errors.New("non-canonical Ed25519 public key")
	}

	// -x^2 + y^2 = 1 + d*x^2*y^2, hence
	// x^2 = (y^2-1)/(d*y^2+1).
	ySquared := edwardsMul(y, y)
	numerator := edwardsSub(ySquared, big.NewInt(1))
	denominator := edwardsAdd(edwardsMul(edwardsD, ySquared), big.NewInt(1))
	inverse := new(big.Int).ModInverse(denominator, edwardsP)
	if inverse == nil {
		return extendedEdwardsPoint{}, errors.New("invalid Ed25519 public key")
	}
	xSquared := edwardsMul(numerator, inverse)
	x := new(big.Int).ModSqrt(xSquared, edwardsP)
	if x == nil {
		return extendedEdwardsPoint{}, errors.New("Ed25519 public key is not on the curve")
	}
	if x.Bit(0) != xSign {
		x.Sub(edwardsP, x)
	}
	if x.Sign() == 0 && xSign != 0 {
		return extendedEdwardsPoint{}, errors.New("non-canonical Ed25519 public key sign bit")
	}
	return extendedEdwardsPoint{
		x: x,
		y: y,
		z: big.NewInt(1),
		t: edwardsMul(x, y),
	}, nil
}

func edwardsScalarMult(point extendedEdwardsPoint, scalar *big.Int) extendedEdwardsPoint {
	result := extendedEdwardsPoint{
		x: big.NewInt(0),
		y: big.NewInt(1),
		z: big.NewInt(1),
		t: big.NewInt(0),
	}
	addend := point
	for bit := 0; bit < scalar.BitLen(); bit++ {
		if scalar.Bit(bit) != 0 {
			result = edwardsPointAdd(result, addend)
		}
		addend = edwardsPointAdd(addend, addend)
	}
	return result
}

// edwardsPointAdd is the complete extended-coordinate addition law for the
// a=-1 twisted Edwards curve. All intermediate values are reduced modulo p.
func edwardsPointAdd(left, right extendedEdwardsPoint) extendedEdwardsPoint {
	a := edwardsMul(edwardsSub(left.y, left.x), edwardsSub(right.y, right.x))
	b := edwardsMul(edwardsAdd(left.y, left.x), edwardsAdd(right.y, right.x))
	c := edwardsMul(edwardsTwoD, edwardsMul(left.t, right.t))
	d := edwardsMul(big.NewInt(2), edwardsMul(left.z, right.z))
	e := edwardsSub(b, a)
	f := edwardsSub(d, c)
	g := edwardsAdd(d, c)
	h := edwardsAdd(b, a)
	return extendedEdwardsPoint{
		x: edwardsMul(e, f),
		y: edwardsMul(g, h),
		z: edwardsMul(f, g),
		t: edwardsMul(e, h),
	}
}

func (point extendedEdwardsPoint) isIdentity() bool {
	return point.z.Sign() != 0 && point.x.Sign() == 0 && point.y.Cmp(point.z) == 0
}

func edwardsAdd(left, right *big.Int) *big.Int {
	return new(big.Int).Mod(new(big.Int).Add(left, right), edwardsP)
}

func edwardsSub(left, right *big.Int) *big.Int {
	return new(big.Int).Mod(new(big.Int).Sub(left, right), edwardsP)
}

func edwardsMul(left, right *big.Int) *big.Int {
	return new(big.Int).Mod(new(big.Int).Mul(left, right), edwardsP)
}

func littleEndianInteger(encoded []byte) *big.Int {
	reversed := make([]byte, len(encoded))
	for i := range encoded {
		reversed[len(encoded)-1-i] = encoded[i]
	}
	return new(big.Int).SetBytes(reversed)
}
